import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default marker icon not displaying
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

const MapComponent = () => {
  const [position, setPosition] = useState([25.276987, 55.296249]); // Default to Dubai
  const [hasLocation, setHasLocation] = useState(false);

  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        setPosition([latitude, longitude]);
        setHasLocation(true);
      },
      () => {
        setHasLocation(false); // Geolocation denied
      }
    );
  }, []);

  return (
    <div style={{ marginTop: '40px', borderRadius: '12px', overflow: 'hidden' }}>
      <h3 style={{ textAlign: 'center' }}>🌍 Your Current Location</h3>
      <MapContainer center={position} zoom={12} style={{ height: '400px', width: '100%' }}>
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution="&copy; OpenStreetMap contributors"
        />
        <Marker position={position}>
          <Popup>{hasLocation ? 'You are here' : 'Location not shared'}</Popup>
        </Marker>
      </MapContainer>
    </div>
  );
};

export default MapComponent;
